1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
59	/**
60	 * Enchantment is read by two unrelated rules with different cut-offs: this one
61	 * charges a premium surcharge from 5 up, and REDUCED_REIMBURSEMENT_THRESHOLD
62	 * halves a claim from 8 up. Each threshold is named after the rule it gates so
63	 * the two cannot be mistaken for one shared notion of "highly enchanted".
64	 */
65	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
66	const LOYALTY_DISCOUNT_PERCENT = 20;
67	const LOYALTY_THRESHOLD_YEARS = 2;
68	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
69	
70	/**
71	 * Everything the pricing rules need to know about an item type lives here, so
72	 * that "what is a rune?" has a single answer. Components are the small parts
73	 * (runes, moonstones) that can be bought as a building block; main items
74	 * (swords, amulets, ...) never form a block.
75	 */
76	const ITEM_TYPES: Record<
77	  string,
78	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
79	> = {
80	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
81	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
82	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
83	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
84	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
85	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
86	};
87	
88	/** A building block of 3 alike components is offered at this base premium. */
89	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
90	const COMPONENT_BLOCK_SIZE = 3;
91	
92	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
93	const countByType = (items: Item[]): [string, number][] => {
94	  const counts = new Map<string, number>();
95	  for (const item of items) {
96	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	  }
98	  return [...counts];
99	};
100	
101	/**
102	 * Prices every item of one type together, because exactly 3 alike components
103	 * form a block charged as one. "Alike" means the same type, and the block does
104	 * not repeat: 4 or 7 runes are each priced per item.
105	 */
106	const basePremiumForType = (type: string, count: number): number => {
107	  const { unitPremium, isComponent } = ITEM_TYPES[type];
108	  return isComponent && count === COMPONENT_BLOCK_SIZE
109	    ? COMPONENT_BLOCK_BASE_PREMIUM
110	    : count * unitPremium;
111	};
112	
113	const sumOfBasePremiums = (items: Item[]): number =>
114	  countByType(items).reduce(
115	    (sum, [type, count]) => sum + basePremiumForType(type, count),
116	    0,
117	  );
118	
119	/**
120	 * A rule whose rate is ADDED to those of every other matching rule. Read with
121	 * filter+reduce: matching several rules charges for each.
122	 *
123	 * Distinct from ExclusiveRule<T> below, which has the same {appliesTo, rate}
124	 * shape but the opposite semantics. The two are separate named types rather
125	 * than one shared shape so that the reader — and the compiler — cannot mistake
126	 * a stacking table for a first-match-wins one.
127	 */
128	interface StackingRule<T> {
129	  appliesTo: (subject: T) => boolean;
130	  rate: number;
131	}
132	
133	/**
134	 * A rule that is an ALTERNATIVE to the others: the first match wins and the
135	 * rest are skipped. Read with find. Order is therefore meaningful — it encodes
136	 * precedence, and reordering the table changes results.
137	 */
138	interface ExclusiveRule<T> {
139	  appliesTo: (subject: T) => boolean;
140	  rate: number;
141	}
142	
143	/**
144	 * Item-specific modifiers: each applies to one item and is charged as a
145	 * percentage of THAT item's unit premium, never of the policy total.
146	 * They stack — an item matching several rules is charged for each.
147	 *
148	 * Unit premium, not the item's share of the policy base: the two differ only
149	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
150	 * no test pins down a surcharged component yet. Revisit when one does.
151	 */
152	const ITEM_MODIFIERS: StackingRule<Item>[] = [
153	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
154	  {
155	    appliesTo: (item) =>
156	      (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD,
157	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
158	  },
159	];
160	
161	const surchargeForItem = (item: Item): number =>
162	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
163	    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].unitPremium, rate),
164	    0,
165	  );
166	
167	const sumOfItemSurcharges = (items: Item[]): number =>
168	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
169	
170	/**
171	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
172	 * premium (the sum of item base premiums, before any item surcharge), so no
173	 * modifier is ever computed on top of another. Discounts carry a negative rate.
174	 */
175	interface PolicyContext {
176	  customer: Customer;
177	  /** Quotes already issued to this customer earlier in the scenario. */
178	  previousContracts: number;
179	}
180	
181	const POLICY_MODIFIERS: StackingRule<PolicyContext>[] = [
182	  // Always applies: every item in a quote is treated as a first insurance,
183	  // regardless of how long the customer has been with the MHPCO.
184	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
185	  {
186	    // Negative rate: a discount is just a surcharge pointing the other way, so
187	    // it needs no separate code path and cannot stack onto another modifier.
188	    appliesTo: ({ customer }) =>
189	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
190	    rate: -LOYALTY_DISCOUNT_PERCENT,
191	  },
192	  {
193	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
194	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
195	  },
196	];
197	
198	const sumOfPolicyAdjustments = (
199	  context: PolicyContext,
200	  policyBasePremium: number,
201	): number =>
202	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
203	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
204	    0,
205	  );
206	
207	const premiumFor = (context: PolicyContext, items: Item[]): number => {
208	  const policyBasePremium = sumOfBasePremiums(items);
209	  return Math.ceil(
210	    policyBasePremium +
211	      sumOfItemSurcharges(items) +
212	      sumOfPolicyAdjustments(context, policyBasePremium) +
213	      PROCESSING_FEE,
214	  );
215	};
216	
217	/** A policy created by a quote step, tracked so later claims can draw on it. */
218	interface Policy {
219	  items: Item[];
220	  remainingCap: number;
221	}
222	
223	const DEDUCTIBLE_PER_DAMAGE = 100;
224	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
225	
226	const insuranceSumOf = (items: Item[]): number =>
227	  items.reduce((sum, item) => sum + ITEM_TYPES[item.type].insuranceValue, 0);
228	
229	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
230	const REDUCED_REIMBURSEMENT_PERCENT = 50;
231	
232	/** Reimbursed in full when no clause below claims the item. */
233	const FULL_REIMBURSEMENT_PERCENT = 100;
234	const DRAGON_MATERIAL = "dragon";
235	
236	/**
237	 * Clauses that change how much of a damage is reimbursed. Exclusive and ordered
238	 * by precedence, because clauses overlap (a highly enchanted dragon-material
239	 * item matches more than one) and they are alternatives — unlike the stacking
240	 * ITEM_MODIFIERS, which the {appliesTo, rate} shape would otherwise suggest.
241	 */
242	const REIMBURSEMENT_CLAUSES: ExclusiveRule<Item>[] = [
243	  {
244	    appliesTo: (item) =>
245	      (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD,
246	    rate: REDUCED_REIMBURSEMENT_PERCENT,
247	  },
248	  // Listed after the clause above so that a highly enchanted dragon item is
249	  // still reimbursed at 50 %. This entry yields exactly what the no-clause
250	  // default yields, so removing it would not change any current result — it is
251	  // here because the spec states dragon material as a rule, and because the
252	  // ordering is what makes the 50 % rule win.
253	  {
254	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
255	    rate: FULL_REIMBURSEMENT_PERCENT,
256	  },
257	];
258	
259	const reimbursementRateFor = (item: Item): number =>
260	  REIMBURSEMENT_CLAUSES.find(({ appliesTo }) => appliesTo(item))?.rate ??
261	  FULL_REIMBURSEMENT_PERCENT;
262	
263	/**
264	 * The clause is applied to the damage first; the deductible comes off whatever
265	 * the clause leaves.
266	 */
267	const payoutForDamage = (damage: Damage, insuredItems: Item[]): number => {
268	  // Unguarded: no test yet describes a damage naming an item the policy does
269	  // not cover. The "claim references an item not covered" test will force this
270	  // honest.
271	  const damagedItem = insuredItems.find(
272	    (item) => item.type === damage.itemType,
273	  ) as Item;
274	  return (
275	    percent(damage.amount, reimbursementRateFor(damagedItem)) -
276	    DEDUCTIBLE_PER_DAMAGE
277	  );
278	};
279	
280	/**
281	 * The contract a quote step issues: what it covers, and how much of its cap is
282	 * still available to later claims.
283	 */
284	const policyFor = (items: Item[]): Policy => ({
285	  items,
286	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
287	});
288	
289	/**
290	 * What an incident is worth against a policy, as a pure calculation: each
291	 * damage is settled on its own (own clause, own deductible) and the results are
292	 * added up. Drawing this down from the policy's cap is the caller's job.
293	 */
294	const payoutForIncident = (
295	  incident: ClaimStep["incident"],
296	  insuredItems: Item[],
297	): number =>
298	  incident.damages.reduce(
299	    (sum, damage) => sum + payoutForDamage(damage, insuredItems),
300	    0,
301	  );
302	
303	/**
304	 * Steps are executed in order because a step's result can depend on the ones
305	 * before it: the count of contracts already issued decides the follow-up
306	 * discount, and the policies a quote registers are what later claims draw on.
307	 */
308	export const runScenario = (scenario: Scenario): ScenarioResult => {
309	  let previousContracts = 0;
310	  const policies = new Map<number, Policy>();
311	
312	  const results = scenario.steps.map((step, index): StepResult => {
313	    if (step.op === "claim") {
314	      // Unguarded: no test yet describes a claim naming a policy that was never
315	      // quoted. The "claim references an item/policy not in the policy" test
316	      // will force this honest.
317	      const policy = policies.get(step.policy) as Policy;
318	      // The cap is a ceiling, not just a running total: once it is exhausted a
319	      // claim is paid only what is left of it.
320	      // Rounded down, and only here: per-damage amounts stay fractional so a
321	      // multi-item incident is not rounded once per damage.
322	      const payout = Math.floor(
323	        Math.min(
324	          payoutForIncident(step.incident, policy.items),
325	          policy.remainingCap,
326	        ),
327	      );
328	      // The one mutation in the module, kept here beside the scenario's other
329	      // cross-step state: what this claim consumes has to be visible to every
330	      // later claim on the same policy.
331	      policy.remainingCap -= payout;
332	      return { payout, remainingCap: policy.remainingCap };
333	    }
334	
335	    const premium = premiumFor(
336	      { customer: scenario.customer, previousContracts },
337	      step.items,
338	    );
339	    policies.set(index, policyFor(step.items));
340	    // Counted after pricing, so a quote never discounts itself, and only for
341	    // quotes, because a claim does not issue a contract.
342	    previousContracts += 1;
343	    return { premium };
344	  });
345	  return { results };
346	};
